//! Fixture parity tests for the Spark BiCodec decode port.
//!
//! Fixtures live in `testdata/spark_bicodec/`, regenerated by
//! `tools/gen_spark_bicodec_fixtures.py` against the pinned mlx-audio
//! commit. The tiny seeded checkpoint stores the reference module tree
//! with the raw torch layouts the reference sanitize chain consumes, so
//! both layout paths of every loader stay exercised. Tensors are
//! float-tolerant; the FSQ implicit codebook is exact.

use std::path::{Path, PathBuf};

use super::BiCodec;
use turbospark_model_io::safetensors::SafetensorsFile;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/spark_bicodec")
        .join(name)
}

fn read_json(name: &str) -> serde_json::Value {
    let text = std::fs::read_to_string(testdata(name)).expect(name);
    serde_json::from_str(&text).expect(name)
}

fn floats(value: &serde_json::Value) -> Vec<f32> {
    value
        .as_array()
        .expect("float array")
        .iter()
        .map(|v| v.as_f64().expect("f64") as f32)
        .collect()
}

fn load_model(case: &str) -> BiCodec {
    let config = read_json("manifest.json");
    let yaml = std::fs::read_to_string(testdata(&format!("{case}/config.yaml"))).unwrap();
    let parsed = super::BiCodecConfig::from_yaml(&yaml).unwrap();
    assert_eq!(
        parsed.decoder.rates.iter().product::<usize>(),
        config["upsample_rate"].as_u64().unwrap() as usize
    );
    let file = SafetensorsFile::open(&testdata(&format!("{case}/model.safetensors"))).unwrap();
    BiCodec::load(parsed, &file).unwrap()
}

#[test]
fn detokenize_matches_reference_trace() {
    let traces = read_json("detokenize/traces.json");
    let model = load_model("detokenize");
    let tolerance = traces["tolerance"].as_f64().unwrap() as f32;
    for case in traces["cases"].as_array().expect("cases") {
        let semantic: Vec<i32> = case["semantic_tokens"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_i64().unwrap() as i32)
            .collect();
        let global: Vec<i32> = case["global_tokens"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_i64().unwrap() as i32)
            .collect();
        let want = floats(&case["waveform"]);
        let got = model.detokenize(&semantic, &global).unwrap();
        assert_eq!(got.len(), want.len(), "case {}", case["name"]);
        let mut max_diff = 0.0f32;
        for (a, b) in got.iter().zip(&want) {
            max_diff = max_diff.max((a - b).abs());
        }
        assert!(
            max_diff <= tolerance,
            "case {} diff {max_diff} > {tolerance}",
            case["name"]
        );
        println!("case {} max diff {max_diff:.3e}", case["name"]);
    }
}

#[test]
fn empty_and_out_of_range_tokens_are_errors() {
    let model = load_model("detokenize");
    let global: Vec<i32> = (0..model.config.speaker_encoder.token_num)
        .map(|v| v as i32)
        .collect();
    // The reference empty-semantic placeholder crashes upstream.
    assert!(model.detokenize(&[], &global).is_err());
    let bad_semantic = model.config.quantizer.codebook_size as i32;
    assert!(model.detokenize(&[bad_semantic], &global).is_err());
    assert!(model.detokenize(&[-1], &global).is_err());
    let bad_global = model
        .config
        .speaker_encoder
        .fsq_levels
        .iter()
        .product::<usize>() as i32;
    assert!(model.detokenize(&[0], &[bad_global]).is_err());
    let wrong_global_len = model.config.speaker_encoder.token_num + 1;
    let pad: Vec<i32> = (0..wrong_global_len).map(|v| v as i32).collect();
    assert!(model.detokenize(&[0], &pad).is_err());
}

#[test]
fn config_validation_rejects_inconsistent_geometry() {
    // The mlx-audio dataclass defaults (prenet out 256, speaker out
    // 512) cannot broadcast the condition add; the config gate must
    // reject that combination the way the reference would fail.
    let yaml = "audio_tokenizer:\n  quantizer:\n    input_dim: 16\n    codebook_size: 32\n    codebook_dim: 4\n  speaker_encoder:\n    input_dim: 8\n    out_dim: 12\n    latent_dim: 4\n    token_num: 3\n    fsq_levels: [3, 3, 3, 3]\n    fsq_num_quantizers: 1\n  prenet:\n    input_channels: 16\n    vocos_dim: 8\n    vocos_intermediate_dim: 16\n    vocos_num_layers: 1\n    out_channels: 10\n    condition_dim: 12\n    sample_ratios: [1, 1]\n  decoder:\n    input_channel: 10\n    channels: 8\n    rates: [2]\n    kernel_sizes: [4]\n    d_out: 1\n";
    let err = super::BiCodecConfig::from_yaml(yaml).unwrap_err();
    assert!(
        err.to_string().contains("out_channels 10 must equal"),
        "{err}"
    );
}
